    char* line = NULL;
    size_t len = 0;

    char* first_line = NULL;
    size_t first_len = 0;

    while (getline(&line, &len, file)!= -1) {
        if (first_line == NULL) {
            first_line = malloc(len);
            strcpy(first_line, line);
            first_len = len;
            continue;
        }

        printf("%s", line);
