import java.net.URL;

public class ClassX {
    /**
     * Hakee sisältöä luodusta URL-osoitteesta isäntää validoimalla.
     * 
     * Tämä toiminto puhdistaa isännän tarkistamalla virheelliset merkit, kuten välilyönnit.
     */
    public void validate(String url) {
        url = url.trim();
        if (url.startsWith("http://")) {
            url = url.substring(7);
        }
        if (url.startsWith("https://")) {
            url = url.substring(8);
        }
        if (url.startsWith("www.")) {
            url = url.substring(4);
        }
        String[] parts = url.split("/");
        url = parts[0];
        for (int i = 1; i < parts.length; i++) {
            if (parts[i].length() == 0) {
                continue;
            }
            String[] ps = parts[i].split("\\.");
            if (ps.length > 2) {
                String rest = "";
                for (int j = 2; j < ps.length; j++) {
                    rest += "." + ps[j];
                }
                url += rest;
            } else {
                url += "." + parts[i];
            }
        }
        System.out.println(url);
    }
}

