import org.apache.commons.io.FilenameUtils;

public class FileUtils {

    public static List<String> readFile(String fileName) throws IOException {
        return readFile(fileName, Charset.defaultCharset());
    }

    public static List<String> readFile(String fileName, Charset charset) throws IOException {
        Path path = Paths.get(fileName);

        return readAllLines(path, charset);
    }

    public static List<String> readAllLines(Path path) throws IOException {
        return readAllLines(path, Charset.defaultCharset());
    }

    public static List<String> readAllLines(Path path, Charset charset) throws IOException {
        List<String> lines = new ArrayList<>();

        try (Stream<String> stream = Files.lines(path, charset)) {
            stream.forEach(line -> lines.add(line));
        }

        return lines;
    }

    public static String getFileName(String fullFileName) {
        return FilenameUtils.removeExtension(FilenameUtils.getName(fullFileName));
    }

    public static void renameFile(String oldFileName, String newFileName) {
        File oldFile = new File(oldFileName);

        if (oldFile.exists()) {
            File newFile = new File(newFileName);

            oldFile.renameTo(newFile);
        }
    }

    public static void deleteFile(String fileName) {
        File file = new File(fileName);

        if (file.exists()) {
            file.delete();
        }
    }

    public static void deleteDirectory(String directoryName) {
        File directory = new File(directoryName);

        if (directory.exists()) {
            deleteDirectory(directory);
        }
