package org.hackerrank.challenge.algorithms.warmup;

import java.util.Scanner;

/*
 * https://www.hackerrank.com/challenges/diagonal-difference
 */
public class DiagonalDifference {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        scanner.nextLine();
        int[][] matrix = new int[N][N];
        for (int i = 0; i < N; i++) {
            String[] line = scanner.nextLine().split(" ");
            for (int j = 0; j < N; j++) {
                matrix[i][j] = Integer.valueOf(line[j]);
            }
        }
        scanner.close();
        int sumLeftToRight = 0;
        int sumRightToLeft = 0;
        for (int i = 0; i < N; i++) {
            sumLeftToRight += matrix[i][i];
            sumRightToLeft += matrix[i][N - 1 - i];
        }
        System.out.println(Math.abs(sumLeftToRight - sumRightToLeft));
    }
}
