package vn.asiantech.internship.asiantech.helper;

import com.auth0.jwt.JWT;
import com.auth0.jwt.JWTVerifier;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.exceptions.JWTVerificationException;

import java.util.Date;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Class JwtHelper.
 *
 * @author 
 * @version 1.0
 */
public class JwtHelper {
    /**
     * The Constant SECRET.
     */
    private static final String SECRET = "asiantech";
    /**
     * The Constant EXPIRE_TIME.
     */
    private static final long EXPIRE_TIME = TimeUnit.DAYS.toMillis(10);
    /**
     * The Constant ALGORITHM.
     */
    private static final Algorithm ALGORITHM = Algorithm.HMAC256(SECRET);

    /**
     * Verify token.
     *
     * @param token the token
     * @return the map
     */
    public static Map<String, Object> verifyToken(String token) {
        try {
            JWTVerifier verifier = JWT.require(ALGORITHM).build();
            return verifier.verify(token).getClaims();
        } catch (JWTVerificationException e) {
            throw new RuntimeException("Token is invalid!");
        }
    }

    /**
     * Generate token.
     *
     * @param claims the claims
     * @return the string
     */
    public static String generateToken(Map<String, Object> claims) {
        Date now = new Date();
        Date expiryDate = new Date(now.getTime() + EXPIRE_TIME);
        return JWT.create()
               .withIssuer("asiantech")
               .withIssuedAt(now)
               .withExpiresAt(expiryDate)
               .withClaims(claims)
               .sign(ALGORITHM);
    }
}
