public class AlgorithmUtils {

    public static List<Algorithm> getAlgorithmList(String json) {
        List<Algorithm> algorithmList = null;
        try {
            JSONObject jsonObject = new JSONObject(json);
            JSONArray jsonArray = jsonObject.getJSONArray("algorithms");
            algorithmList = new ArrayList<Algorithm>();
            for (int i = 0; i < jsonArray.length(); i++) {
                JSONObject algorithmObject = jsonArray.getJSONObject(i);
                Algorithm algorithm = new Algorithm();
                algorithm.setId(algorithmObject.getString("id"));
                algorithm.setName(algorithmObject.getString("name"));
                algorithm.setVersion(algorithmObject.getString("version"));
                algorithm.setUri(algorithmObject.getString("uri"));
                algorithm.setAlgorithmType(algorithmObject.getString("algorithmType"));
                algorithm.setDescription(algorithmObject.getString("description"));
                algorithm.setLanguage(algorithmObject.getString("language"));
                algorithm.setLanguageVersion(algorithmObject.getString("languageVersion"));
                algorithmList.add(algorithm);
            }
        } catch (JSONException e) {
            e.printStackTrace();
        }
        return algorithmList

