package com.mizan.jumat.controller;

import com.mizan.jumat.model.User;
import com.mizan.jumat.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api")
public class MainController {

    @Autowired
    private UserService userService;

    @PostMapping("/login")
    public ResponseEntity<Map<String, String>> login(@RequestBody Map<String, String> user) {
        Map<String, String> result = new HashMap<>();
        User userEntity = userService.findByEmail(user.get("email"));
        if (userEntity == null) {
            result.put("message", "Email or Password is wrong");
            return new ResponseEntity<>(result, HttpStatus.BAD_REQUEST);
        }
        if (!userService.checkPassword(userEntity.getPassword(), user.get("password"))) {
            result.put("message", "Email or Password is wrong");
            return new ResponseEntity<>(result, HttpStatus.BAD_REQUEST);
        }
        result.put("token", userEntity.getToken());
        return new ResponseEntity<>(result, HttpStatus.OK);
    }
}
