/**
 * Deze klasse bevat de tokenheader van een token.
 */
public class TokenHeader {
    /**
     * De algoritme van deze token.
     */
    private final String algorithm;

    /**
     * De token van deze header.
     */
    private final String token;

    /**
     * De expiretime van deze header.
     */
    private final long expireTime;

    /**
     * De lijst met claims van deze header.
     */
    private final List<Claim> claims;

    /**
     * De constructor van deze klasse.
     * 
     * @param algorithm   De algoritme van deze token.
     * @param token       De token van deze header.
     * @param expireTime  De expiretime van deze header.
     * @param claims      De lijst met claims van deze header.
     */
    public TokenHeader(final String algorithm, final String token, final long expireTime, final List<Claim> claims) {
        this.algorithm = algorithm;
        this.token = token;
        this.expireTime = expireTime;
        this.claims = claims;
    }

    /**
     * Geeft de algoritme van deze header terug.
     * 
     * @return De algoritme van deze header.
     */
