public class ex07_solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter number of students: ");
        int students = scanner.nextInt();

        System.out.print("Enter number of quizs: ");
        int quizs = scanner.nextInt();

        int[] grades = new int[quizs];

        for (int i = 0; i < quizs; i++) {
            System.out.print("Enter grade of quiz " + (i + 1) + ": ");
            grades[i] = scanner.nextInt();
        }

        int sum = 0;

        for (int grade : grades) {
            sum += grade;
        }

        double average = (double) sum / quizs;
        System.out.println("The average of quizs is: " + average);
    }
}
