package org.tbot.utils.web;

import java.io.IOException;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;

import org.tbot.utils.Random;

/**
 * General web utilities including connection, downloading, etc.
 */
public class WebUtils {

    /**
     * Downloads the given URL and returns its content as a String.
     * 
     * @param url
     *            The URL to download
     * @param isStatic
     *            Whether this is a static URL (i.e. it doesn't require any
     *            authentication or cookies)
     * @param cookies
     *            Cookies to send with the request
     * @return The downloaded content
     * @throws IOException
     *             If there is an error downloading the URL
     */
    public static String downloadWebpage(String url, boolean isStatic, String... cookies) throws IOException {
        HttpURLConnection connection = null;
        try {
            URL connectionUrl = new URL(url);
            if (isStatic) {
                connection = (HttpURLConnection) connectionUrl.openConnection();
            } else {
                connection = (HttpURLConnection) connectionUrl.openConnection();
                connection.setRequestProperty("Cookie", String.join("; ", cookies));
            }
            try (InputStream content = connection.getInputStream()) {
                return new String(content.readAllBytes());
            }
        } finally {
            if (connection!= null) {
                connection.disconnect();
            }
        }
    }

    /**
     * Returns a random user agent string.
     * 
     * @return A random user agent string
     */
    public static String getUserAgent() {
        return Random.getRandomUserAgent();
    }
}
