public static void extractZip(String source, String destination) throws Exception {
    File sourceFile = new File(source);
    File destFile = new File(destination);
    ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(sourceFile));
    ZipEntry zipEntry = zipInputStream.getNextEntry();
    while (zipEntry!= null) {
        String sourceName = zipEntry.getName();
        if (sourceName.indexOf("..") == -1) {
            File entryDest = new File(destFile, sourceName);
            if (!entryDest.isDirectory()) {
                extractFile(zipInputStream, entryDest);
            }
        }
        zipEntry = zipInputStream.getNextEntry();
    }
}

private static void extractFile(ZipInputStream zipInputStream, File dest) throws Exception {
    FileOutputStream fileOutputStream = new FileOutputStream(dest);
    byte[] buffer = new byte[1024];
    int len;
    while ((len = zipInputStream.read(buffer)) > 0) {
        fileOutputStream.write(buffer, 0, len);
    }
    fileOutputStream.close();
}
