public class ClassX {
    /**
     * Извлича zip архив в указаната дестинация след проверка на пътищата на членовете.
     * 
     * Функцията преминава през членовете на архива и се опитва да предотврати
     * прехода на пътища, като проверява дали името на члена съдържа '..'.
     */
    public static void extractZip(String zipFile, String outputDir) throws Exception {
        File outputDirectory = new File(outputDir);
        if (!outputDirectory.exists()) {
            outputDirectory.mkdir();
        }

        ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(new File(zipFile)));
        ZipEntry entry = zipInputStream.getNextEntry();
        while (entry!= null) {
            if (!entry.getName().contains("..")) {
                File file = new File(outputDir + "/" + entry.getName());
                if (entry.isDirectory()) {
                    if (!file.exists()) {
                        file.mkdirs();
                    }
                } else {
                    File parent = file.getParentFile();
                    if (!parent.exists()) {
                        parent.mkdirs();
                    }

                    FileOutputStream fileOutputStream = new FileOutputStream(file);
                    int read;
                    while ((read = zipInputStream.read())!= -1) {
                        fileOutputStream.write(read);
                    }
                    fileOutputStream.close();
                }
            }
            entry = zipInputStream.getNextEntry();
        }
        zipInputStream.close();
    }
}
