        String zipFile = args[1];
        File targetFile = new File(targetDir);
        if (!targetFile.exists()) {
            throw new RuntimeException("Directory does not exist: " + targetDir);
        }
        if (!targetFile.isDirectory()) {
            throw new RuntimeException("Target is not a directory: " + targetDir);
        }
        File zip = new File(zipFile);
        if (!zip.exists()) {
            throw new RuntimeException("Zip file does not exist: " + zipFile);
        }
        if (!zip.isFile()) {
            throw new RuntimeException("Zip file is not a file: " + zipFile);
        }
        ZipInputStream zis = new ZipInputStream(new FileInputStream(zip));
        ZipEntry entry;
        while ((entry = zis.getNextEntry())!= null) {
            String entryName = entry.getName();
            if (entryName.contains("..")) {
                throw new RuntimeException("Zip file contains '..': " + entryName);
