        return;
    }

    if (zipFile.getAbsolutePath().contains(File.separator + ".." + File.separator)) {
        System.out.println("You may not unpack to parent directory");
        return;
    }

    if (unpackTo.getAbsolutePath().contains(File.separator + ".." + File.separator)) {
        System.out.println("You may not unpack to parent directory");
        return;
    }

    if (unpackTo.getAbsolutePath().contains(zipFile.getAbsolutePath())) {
        System.out.println("You may not unpack to parent directory");
        return;
    }

    try (ZipInputStream zipStream = new ZipInputStream(new FileInputStream(zipFile))) {
        ZipEntry entry;
        while ((entry = zipStream.getNextEntry())!= null) {
            if (entry.getName().contains(File.separator + ".." + File.separator)) {
                System.out.println("Wrong file name");
                return;
            }
        }

        if (!unpackTo.exists()) {
            unpackTo.mkdirs();
        }

        for (ZipEntry entry = zipStream.getNextEntry(); entry!= null; entry = zipStream.getNextEntry()) {
            if (entry.getName().contains(File.separator + ".." + File.separator)) {
                System.out.println("Wrong file name");
                return;
            }

            if (!entry.isDirectory()) {
                File file = new File(unpackTo, entry.getName());
                file.getParentFile().mkdirs();

                try (FileOutputStream out = new FileOutputStream(file)) {
                    byte[] buffer = new byte[1024];
                    int len;
