@Solution(id = 496,
        name = "Next Greater Element I",
        desc = "You are given two arrays (without duplicates) nums1 and nums2 where nums1" +
                "’s elements are subset of nums2. Find all the next greater numbers for" +
                "nums1’s elements in the corresponding places of nums2. The Next Greater" +
                " Number of a number x in nums1 is the first greater number to its right in" +
                "nums2. If it does not exist, output -1 for this number.",
        url = "https://leetcode.com/problems/next-greater-element-i/")
public class Solution_496 {
    public int[] nextGreaterElement(int[] findNums, int[] nums) {
        int[] result = new int[findNums.length];
        if (findNums == null || findNums.length == 0 || nums == null || nums.length == 0) {
            return result;
        }
        Map<Integer, Integer> map = new HashMap<>();
        int[] nums1 = Arrays.copyOf(nums, nums.length);
        for (int i = nums.length - 1; i >= 0; i--) {
            map.put(nums1[i], i);
            nums1[i] = -1;
        }
        for (int i = 0; i < findNums.length; i++) {
            for (int j = map.get(findNums[i]); j < nums.length; j++) {
                if (nums[j] > findNums[i]) {
                    result[i] = nums[j];
                    break;
                }
            }
        }
        return result;
    }
}
