   * @param filename The file to read.
   * @return The file contents.
   * @throws IOException If an unexpected IO exception occurred.
   */
  public static byte[] readBytesFromClasspath(String filename) throws IOException {
    return readBytes(getClass().getClassLoader().getResourceAsStream(filename));
  }

  /**
   * Read a file from the classpath into a byte array.
   * 
   * @param filename The file to read.
   * @return The file contents.
   * @throws IOException If an unexpected IO exception occurred.
   */
  public static byte[] readBytesFromClasspath(URL filename) throws IOException {
    return readBytes(filename.openStream());
  }

  /**
   * Read a file from the classpath into a byte array.
   * 
   * @param filename The file to read.
   * @return The file contents.
   * @throws IOException If an unexpected IO exception occurred.
   */
  public static byte[] readBytesFromClasspath(Class<?> clazz, String filename) throws IOException {
    return readBytes(clazz.getClassLoader().getResourceAsStream(filename));
  }

  /**
   * Read a file from a stream into a byte array.
   * 
   * @param stream The input stream to read from.
   * @return The file contents.
   * @throws IOException If an unexpected IO exception occurred.
   */
  public static byte[] readBytes(InputStream stream) throws IOException {
    byte[] data = new byte[stream.available()];
    stream.read(data);
    return data;
  }

