package pt.tecnico.learnjava.domain;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static pt.tecnico.learnjava.utils.StringUtils.trimComment;
import static pt.tecnico.learnjava.utils.StringUtils.trimNewLine;

public class ClassBody {
    private List<String> lines;

    public ClassBody(String[] lines) {
        this.lines = new ArrayList<>();
        Collections.addAll(this.lines, lines);
    }

    public ClassBody(List<String> lines) {
        this.lines = lines;
    }

    public void removeLine(int lineNumber) {
        this.lines.remove(lineNumber);
    }

    public void addLine(int lineNumber, String line) {
        this.lines.add(lineNumber, line);
    }

    public void replaceLine(int lineNumber, String line) {
        this.lines.set(lineNumber, line);
    }

    public String get(int lineNumber) {
        return this.lines.get(lineNumber);
    }

    public int size() {
        return this.lines.size();
    }

    public void addLine(String line) {
        this.lines.add(line);
    }

    public void addLineBefore(int lineNumber, String line) {
        this.lines.add(lineNumber, line);
    }

    public List<String> getLines() {
        return this.lines;
    }

    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (String line : this.lines) {
            sb.append(line).append("\n");
        }
        return sb.toString();
    }

    public void trimNewLine() {
        int lastPos = this.lines.size() - 1;
        this.lines.set(lastPos, this.lines.get(lastPos).trim());
    }

    public void trimComment() {
        for (int i = 0; i < this.lines.size(); i++) {
            this.lines.set(i, trimComment(this.lines.get(i)));
        }
    }

    public void trim() {
        this.trimNewLine();
        this.trimComment();
    }

}

