package com.codigofacilito.interviews.models.questions;

public class Question {
    private String text;
    private int id;
    private String answer;
    private int score;
    private String category;

    public Question(String text, int id, String answer, int score, String category) {
        this.text = text;
        this.id = id;
        this.answer = answer;
        this.score = score;
        this.category = category;
    }

    public String getText() {
        return text;
    }

    public void setText(String text) {
        this.text = text;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getAnswer() {
        return answer;
    }

    public void setAnswer(String answer) {
        this.answer = answer;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    @Override
    public String toString() {
        return "Question{" +
                "text='" + text + '\'' +
                ", id=" + id +
                ", answer='" + answer + '\'' +
                ", score=" + score +
                ", category='" + category + '\'' +
                '}';
    }
}
