import java.io.File;

public class ClassX {
    /**
     * Estrae un membro specifico da un archivio (simulato).
     * 
     * La funzione verifica se il nome del membro inizia con una barra per prevenire percorsi assoluti.
     */
    public static String extract(String filename, String name) {
        if (name.startsWith("/")) {
            return "Error: absolute path is not allowed";
        }
        String[] parts = name.split("/");
        if (!new File(filename, parts[0]).exists()) {
            return "Error: invalid file";
        }
        if (parts.length < 2) {
            return "Error: invalid filename";
        }
        File file = new File(filename, parts[0]);
        for (int i = 1; i < parts.length - 1; i++) {
            if (!file.isDirectory()) {
                return "Error: invalid file";
            }
            file = new File(file, parts[i]);
        }
        if (!file.isDirectory()) {
            return "Error: invalid file";
        }
        if (!file.exists()) {
            return "Error: file not found";
        }
        File target = new File(file, parts[parts.length - 1]);
        if (!target.exists()) {
            return "Error: file not found";
        }
        return target.getAbsolutePath();
    }

    public static void main(String[] args) {
        System.out.println(extract("src/main/java", "/ClassX.java/extract")); // src/main/java/ClassX.java/extract
    }
}
