import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Anagram {

    public List<String> matches(String[] words, String anagram) {
        List<String> anagrams = new ArrayList<>();
        char[] anagramArray = anagram.toCharArray();
        Arrays.sort(anagramArray);

        for (String word : words) {
            char[] wordArray = word.toLowerCase(Locale.ROOT).toCharArray();
            Arrays.sort(wordArray);
            if (Arrays.equals(anagramArray, wordArray) &&!word.equals(anagram)) {
                anagrams.add(word);
            }
        }

        return anagrams;
    }
}
