class Mailcap {
    private static final String COMMAND = "mimeopen";
    private static final String[] FILTER = {"text/html", "application/pdf", "image/jpeg"};

    public static void main(String[] args) {
        try {
            String mime_type = args[0];
            if (mime_type.contains(";")) {
                System.out.println("Invalid input");
                return;
            }

            for (String s : FILTER) {
                if (mime_type.contains(s)) {
                    executeCommand(mime_type);
                    return;
                }
            }
            System.out.println("Invalid input");
        } catch (Exception e) {
            System.out.println("Invalid input");
        }
    }

    private static void executeCommand(String mime_type) {
        String[] command = new String[] {"/bin/sh", "-c", COMMAND + " " + mime_type};
        Process process = Runtime.getRuntime().exec(command);

        BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line = null;
        try {
            while ((line = input.readLine())!= null) {
                System.out.println(line);
            }
            input.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
