  onSubmit() {
    this.submitted = true;

    // stop here if form is invalid
    if (this.registerForm.invalid) {
      return;
    }
    let user: User = new User(
      this.registerForm.value['name'],
      this.registerForm.value['email'],
      this.registerForm.value['password']
    );
