    @Override
    public Type visit(ExpressionStatement node) {
        return node.getExpression().accept(this);
    }

    @Override
    public Type visit(PrintStatement node) {
        return node.getExpression().accept(this);
    }

    @Override
    public Type visit(StringExpression node) {
        return new StringType();
