/**
 * This check is for detecting and avoiding "$" in names.
 */
public class AvoidDollarInNamesCheck extends AbstractCheck {

    @Override
    public int[] getDefaultTokens() {
        return new int[] { TokenTypes.IDENT };
    }

    @Override
    public int[] getAcceptableTokens() {
        return new int[] { TokenTypes.IDENT };
    }

    @Override
    public int[] getRequiredTokens() {
        return new int[] {};
    }

    @Override
    public void visitToken(DetailAST ast) {
        int nameLength = ast.getText().length();
        String name = ast.getText();
        if (nameLength > 1 && name.charAt(nameLength - 1) == '$') {
            addViolation(ast);
        }
    }
}
