    public void push(E item) {
        if(size == capacity) {
            this.capacity *= 2;
            E[] temp = (E[]) new Object[capacity];
            for(int i = 0; i < size; i++) {
                temp[i] = arr[i];
            }
            arr = temp;
        }
        arr[size++] = item;
    }

    public E pop() {
        if(size == 0) {
            return null;
        }
        size--;
        return arr[size];
    }

    public E peek() {
        if(size == 0) {
            return null;
        }
        return arr[size - 1];
    }

