package com.exercism.java.exercises.anagram;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Anagram {

    private final String input;

    public Anagram(String input) {
        this.input = input;
    }

    public Set<String> match(String[] candidates) {
        Set<String> result = new HashSet<>();
        for (String candidate : candidates) {
            if (candidate.length() == input.length()) {
                if (Arrays.equals(sort(input), sort(candidate))) {
                    result.add(candidate);
                }
            }
        }
        return result;
    }

    private char[] sort(String str) {
        char[] inputArray = str.toLowerCase().toCharArray();
        Arrays.sort(inputArray);
        return inputArray;
    }
}
