package com.exercism.java.exercises.practice.allergies;

import com.exercism.java.exercises.practice.allergies.Allergen;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class Allergies {
    private static final Map<Integer, Allergen> allergenMap = new HashMap<>();

    static {
        allergenMap.put(1, Allergen.EGGS);
        allergenMap.put(2, Allergen.PEANUTS);
        allergenMap.put(4, Allergen.SNAKES);
        allergenMap.put(8, Allergen.STRAWBERRIES);
    }

    private final int mask;

    public Allergies(int mask) {
        this.mask = mask;
    }

    public boolean isAllergicTo(Allergen allergen) {
        return (mask & allergenMap.get(allergen.getCode()).getCode()) > 0;
    }

    public List<Allergen> list() {
        return allergenMap.entrySet().stream()
               .filter(e -> isAllergicTo(e.getValue()))
               .map(Map.Entry::getValue)
               .collect(Collectors.toList());
    }
}
