     * 
     * @param arr array yang akan di cek
     * @return nilai terbesar dari array
     */
    public static int arrayMaximalAdjacentDifference(int[] arr) {
        int max = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            int diff = Math.abs(arr[i] - arr[i + 1]);
            if (diff > max) {
                max = diff;
            }
        }
