package com.github.pedrovgs.problem36;

import java.util.Arrays;

import static com.github.pedrovgs.common.SortArray.sort;

/**
 * Given an array of integers find the maximum product you can get from three of the integers.
 * 
 * @author 
 * 
 */
public class MaxProductOf3Numbers {

    /**
     * Returns the max product from 3 numbers.
     * 
     * @param array
     * @return max product
     */
    public int maxProduct(int[] array) {
        return maxProduct(array, 3);
    }

    /**
     * Returns the max product from <i>n</i> numbers.
     * 
     * @param array
     * @param n
     * @return max product
     */
    public int maxProduct(int[] array, int n) {
        sort(array);
        int max1 = array[n - 1] * array[n - 2] * array[n - 3];
        int max2 = array[n - 1] * array[0] * array[1];
        return Math.max(max1, max2);
    }

    public static void main(String[] args) {
        MaxProductOf3Numbers test = new MaxProductOf3Numbers();
        int[] array = { 1, 2, 3, 4, 5, 6, 7 };
        System.out.println(test.maxProduct(array));
    }
}
