    }

    public String generateCode(String code, String username) throws Exception {
        if (code.equals("")) {
            return "";
        }
        CodeGeneratorVisitor visitor = new CodeGeneratorVisitor();
        CodeGeneratorParser parser = new CodeGeneratorParser(visitor);
        CodeGeneratorListener listener = new CodeGeneratorListener();
        parser.addParseListener(listener);
        try {
            parser.parse(code);
        } catch (CodeGeneratorException e) {
            return e.getMessage();
        }
        String output = visitor.getOutput();
        String output2 = listener.getOutput();
        if (output2!= null) {
            output = output2;
        }
        return output;
    }
}
