package hu.bme.mit.yakindu.synthesis.java;

import java.util.HashMap;
import java.util.Map;

import hu.bme.mit.yakindu.synthesis.java.expression.Expression;
import hu.bme.mit.yakindu.synthesis.java.expression.LiteralExpression;

public class Template {
	private String content;
	private Map<String, Expression> parameters = new HashMap<>();

	public Template(String content) {
		this.content = content;
	}

	public String getContent() {
		return content;
	}

	public void addParameter(String name, Expression expression) {
		parameters.put(name, expression);
	}

	public String evaluate() {
		String result = content;
		for (String name : parameters.keySet()) {
			result = result.replace(name, parameters.get(name).evaluate());
		}
		return result;
	}

	public static Template fromString(String content) {
		return new Template(content);
	}

	public static Template fromString(String content, Expression... expressions) {
		Template template = new Template(content);
		for (Expression expression : expressions) {
			template.addParameter(expression.getName(), expression);
		}
		return template;
	}

	public static Template fromString(String content, LiteralExpression... expressions) {
		Template template = new Template(content);
		for (LiteralExpression expression : expressions) {
			template.addParameter(expression.getName(), expression);
		}
		return template;
	}
}
