public static String render(String template, Map<String, Object> data) {
    StringBuilder result = new StringBuilder();
    String[] tokens = template.split("\\{\\{\\s*([\\w\\.]+)\\s*\\}\\}");
    for (int i = 0; i < tokens.length; i++) {
        if (i % 2 == 0) {
            result.append(tokens[i]);
        } else {
            String token = tokens[i];
            if (token.contains(".")) {
                String[] parts = token.split("\\.");
                String current = "data";
                for (int j = 0; j < parts.length - 1; j++) {
                    current += "." + parts[j];
                }
                current += ".get(\"" + parts[parts.length - 1] + "\")";
                if (data.get(parts[0]) == null) {
                    throw new IllegalStateException();
                }
                result.append(data.get(parts[0]).toString());
            } else {
                if (data.get(token) == null) {
                    result.append("null");
                } else {
                    result.append(data.get(token).toString());
                }
            }
        }
    }
    return result.toString();
}
