package com.github.kuleshov7.codeassistant.services;

import com.github.kuleshov7.codeassistant.utils.Utils;
import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiFile;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class CodeAssistantServiceImpl implements CodeAssistantService {

    @NotNull
    @Override
    public List<String> getAssistance(
            @NotNull Project project,
            @NotNull PsiFile psiFile,
            @NotNull String question,
            @Nullable String userAnswer) {

        // The project is guaranteed to be an instance of the Java project.
        // The only way to get the project is to open a file.
        // So there are no other projects in the system.
        Path path = Paths.get(psiFile.getVirtualFile().getPath());
        File file = path.toFile();
        Path projectPath = path.getParent();

        List<String> lines = new ArrayList<>();
        try {
            lines = Files.readAllLines(file.toPath());
        } catch (IOException e) {
            e.printStackTrace();
        }

        List<String> result = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (Utils.isComment(line)) {
                continue;
            }

            if (line.contains(question)) {
                String code = Utils.getAssistance(line, userAnswer, projectPath.toString());
                result.add(code);
            }
        }

        return result;
    }
}

