package org.team9.training.assignment.service;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.team9.training.assignment.model.Assignment;
import org.team9.training.assignment.model.Assignment.Status;
import org.team9.training.assignment.repository.AssignmentRepository;

@Service
public class AssignmentService {

	@Autowired
	private AssignmentRepository assignmentRepository;

	public Assignment save(Assignment assignment) {
		return assignmentRepository.save(assignment);
	}

	public Assignment findById(Integer id) {
		return assignmentRepository.findById(id).orElse(null);
	}

	public void update(Assignment assignment) {
		assignmentRepository.save(assignment);
	}

	public void delete(Integer id) {
		assignmentRepository.deleteById(id);
	}

	public void deleteAll() {
		assignmentRepository.deleteAll();
	}

	public Assignment findLastActive() {
		return assignmentRepository.findTop1ByOrderByStartDesc();
	}

	public Assignment findLastFinished() {
		return assignmentRepository.findTop1ByOrderByEndDesc();
	}

	public Assignment findLastByStatus(Status status) {
		return assignmentRepository.findTop1ByStatusOrderByStartDesc(status);
	}

	public Assignment findLastByStatusAndId(Status status, Integer id) {
		return assignmentRepository.findTop1ByStatusAndIdOrderByStartDesc(status, id);
	}

	public Assignment findByStatus(Status status) {
		return assignmentRepository.findTop1ByStatusOrderByStartDesc(status);
	}

}
