    String js = engine.eval(System.console().readLine()).toString();

    // Muuda väljendi üldjuhul nii, et iga operatsioon on eraldi reale
    // ja väljend on samuti reale
    String[] parts = js.split(" ");

    // Kasuta piiramist
    String result = "";
    String last = "";
    for (String part : parts) {
        // Võta väljendist põhioperatsioonid vaid
        if (part.equals("+") || part.equals("-") || part.equals("*") || part.equals("/")) {
            result += last + " " + part + " ";
        } else if (!part.equals("(") &&!part.equals(")")) {
            // Märksõnad võivad ebasobivalt sisaldada.
            // Piiramine, et väljend ei ole mõne muu funktsiooni väljend.
            if (!part.matches("[0-9]+")) {
                break;
            }
            result += "(" + part + ") ";
        }
        last = part;
    }

    // Käivita väljend, mis võtab väljendi põhikalkulatsioon
    engine.eval(result);
