import java.util.Set;

/**
 * Created by anton on 04.03.16.
 */
public class Assistant {
    private static final Map<String, Command> commands = new HashMap<>();
    private static final Set<String> commandNames = new HashSet<>();
    private static final String EXIT_COMMAND = "exit";

    static {
        addCommand(new HelpCommand());
        addCommand(new ExitCommand());
        addCommand(new UnknownCommand());
        addCommand(new MathCommand());
        addCommand(new JavaCommand());
        addCommand(new PythonCommand());
        addCommand(new JavaScriptCommand());
    }

    private static void addCommand(Command command) {
        commands.put(command.getName(), command);
        commandNames.add(command.getName());
    }

    public static void main(String[] args) {
        try {
            while (true) {
                System.out.print("> ");
                String input = readInput();
                String[] commandParts = input.split(" ", 2);
                String command = commandParts[0];
                if (command.startsWith("/") && commandNames.contains(command)) {
                    String input2 = commandParts.length == 2? commandParts[1] : "";
                    Command commandObject = commands.get(command);
                    commandObject.execute(input2);
                } else {
                    UnknownCommand.execute(input);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static String readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        return br.readLine();
    }
}
