import javax.script.ScriptEngineManager

class DynamicTest(private val test: DynamicTestInfo, private val workingDir: File) {
    private val engine: ScriptEngine = ScriptEngineManager().getEngineByName("nashorn")

    private val testName: String = test.name
    private val testCases: List<TestCase> = test.testCases.map { TestCase(it.input, it.output, it.type) }
    private val testType: String = test.testType

    fun execute(): TestResult {
        val testPassed = testCases.all { testCase ->
            val output = executeScript(testCase)
            val passed = output.contains(testCase.expectedOutput)
            if (!passed) {
                val message = "Expected ${testCase.expectedOutput} but got ${output}"
                println("${testCase.type.toString().toLowerCase()} test ${testName} failed. $message")
            }
            passed
        }
        return TestResult(testPassed, testName, testType)
    }

    private fun executeScript(testCase: TestCase): String {
        val script = buildScript(testCase)
        val scriptEngine = engine.apply {
            eval(script)
        }
        return scriptEngine.invokeFunction("main").toString()
    }

    private fun buildScript(testCase: TestCase): String {
        val input = buildScriptInput(testCase)
        val output = buildScriptOutput(testCase)
        val script = buildScript(input, output)
        return script
    }

    private fun buildScriptInput(testCase: TestCase): String {
        val input = testCase.input
        val inputScript = buildScriptInput(input)
        return inputScript
    }

    private fun buildScriptOutput(testCase: TestCase): String {
        val output = testCase.expectedOutput
        val outputScript = buildScriptOutput(output)
        return outputScript
    }

