		for (String line : lines) {
			if (line.startsWith(";")) {
				continue;
			}

			line = line.trim();

			if (line.isEmpty()) {
				continue;
			}

			String[] splittedLine = line.split(" ");

			if (splittedLine.length == 0) {
				continue;
			}

			String instruction = splittedLine[0];

			if (instruction.contains(":")) {
				String[] label = instruction.split(":");
				instructions.add(label[1].trim() + ":");
