public class ArrayDuplicate {
    public static int[] remove(int[] array) {
        int[] result = new int[array.length];
        int j = 0;
        for (int i = 0; i < array.length; i++) {
            boolean unique = true;
            for (int k = 0; k < i; k++) {
                if (array[k] == array[i]) {
                    unique = false;
                }
            }
            if (unique) {
                result[j] = array[i];
                j++;
            }
        }
        return result;
    }
}
