public class task028 {
    public static void main(String[] args) {
        String input = Utils.readInput("Enter a string: ");
        output(input);
    }

    private static void output(String input) {
        if (input == null || input.length() == 0) {
            System.out.println("You have entered an invalid string.");
            return;
        }
        String result = "";
        for (int i = input.length() - 1; i >= 0; i--) {
            result += input.charAt(i);
        }
        System.out.println("String in reverse order: " + result);
    }
}
