 * </ul>
 */
public class FindTheMissingLetter {
    public static char findMissingLetter(char[] array) {
        char low = array[0];
        char high = array[array.length - 1];

        if (low == 'z') {
            return (char) (high + 1);
        } else if ((high - low) == 1) {
            return (char) (high + 1);
        } else {
            return (char) (low + 1);
        }
    }

