package com.github.sormuras.bach.ast;

import com.github.sormuras.bach.ast.util.AstVisitor;
import com.github.sormuras.bach.ast.visitor.ToStringVisitor;

import java.util.Objects;
import java.util.Optional;

import static java.util.Objects.requireNonNull;

public abstract class Ast {
    private final String string;

    public Ast(String string) {
        this.string = requireNonNull(string);
    }

    public abstract <T> T accept(AstVisitor<T> visitor);

    public String getString() {
        return string;
    }

    @Override
    public String toString() {
        return accept(new ToStringVisitor());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Ast ast = (Ast) o;
        return string.equals(ast.string);
    }

    @Override
    public int hashCode() {
        return Objects.hash(string);
    }

    public Optional<Ast> getChild(int index) {
        return Optional.empty();
    }

    public abstract int getChildCount();
}
