package com.devskiller.leetcode.problems.Find_the_Difference;

public class Solution {
    public char findTheDifference(String s, String t) {
        int ascii = 0;
        for (int i = 0; i < s.length(); i++) {
            ascii += s.charAt(i);
        }
        for (int i = 0; i < t.length(); i++) {
            ascii -= t.charAt(i);
        }
        return (char) ascii;
    }
}
