package io.github.fridim.codeassist4j.assistant;

import io.github.fridim.codeassist4j.assistant.assistant.AssistantAction;
import io.github.fridim.codeassist4j.assistant.assistant.AssistantStrategy;
import io.github.fridim.codeassist4j.assistant.assistant.AssistantStrategyFactory;
import io.github.fridim.codeassist4j.assistant.assistant.AssistantStrategyFactoryImpl;
import io.github.fridim.codeassist4j.assistant.assistant.AssistantStrategyResult;

import java.util.List;
import java.util.Map;

public class Assistant {

    private AssistantStrategy assistantStrategy;
    private AssistantStrategyFactory assistantStrategyFactory;

    public Assistant(AssistantStrategyFactory assistantStrategyFactory) {
        this.assistantStrategyFactory = assistantStrategyFactory;
        this.assistantStrategy = assistantStrategyFactory.getAssistantStrategy();
    }

    public String getAssistantMessage(String code) {
        return assistantStrategy.handle(code);
    }

    public static class AssistantStrategyFactoryImpl implements AssistantStrategyFactory {

        @Override
        public AssistantStrategy getAssistantStrategy() {
            return new AssistantStrategyImpl(new AssistantStrategyFactoryImpl());
        }
    }

    private class AssistantStrategyImpl implements AssistantStrategy {

        private AssistantStrategyFactory assistantStrategyFactory;

        private AssistantStrategyImpl(AssistantStrategyFactory assistantStrategyFactory) {
            this.assistantStrategyFactory = assistantStrategyFactory;
        }

        @Override
        public String handle(String code) {
            List<AssistantAction> assistantActions = getAssistantActions(code);
            AssistantStrategyResult assistantStrategyResult = new AssistantStrategyResult();
            for (AssistantAction assistantAction : assistantActions) {
                assistantStrategyResult = assistantAction.handle(assistantStrategyResult);
            }
            return assistantStrategyResult.getAssistantMessage();
        }

        private List<AssistantAction> getAssistantActions(String code) {
            Map<String, String> assistantCode = assistantStrategyFactory.getAssistantCode();
            List<AssistantAction> assistantActions = assistantCode.entrySet()
                   .stream()
                   .map(entry -> AssistantAction.getInstance(entry.getKey(), entry.getValue()))
                   .toList();
            return assistantActions;
        }
    }

}

