import nl.hannahsten.texifyidea.run.compiler.LatexCompilerService.Companion.compilerList
import javax.swing.JComponent

class LatexRunConfigurationEditor(project: Project, configuration: RunConfiguration) : SettingsEditor<RunConfiguration>() {

    private val compilerList = compilerList()
    private val compilerComboBox = JBList(compilerList)
    private val compilerTextField = TextFieldWithBrowseButton(null)
    private val rootDirectoryTextField = TextFieldWithBrowseButton(null)
    private val rootDirectoryBrowseButton = LabeledComponent.create(rootDirectoryTextField, "Root directory:")

    init {
        rootDirectoryBrowseButton.component.addActionListener {
            val descriptor = FileChooserDescriptorFactory.createSingleFolderDescriptor()
            val chooser = descriptor.createFileChooser(project)
            chooser.showDialog(null)
            rootDirectoryTextField.text = chooser.selectedFile?.path
        }

        rootDirectoryTextField.text = configuration.rootDirectory
    }

    override fun resetEditorFrom(configuration: RunConfiguration) {
        compilerComboBox.selectedIndex = compilerComboBox.items.indexOf(configuration.compiler)
        rootDirectoryTextField.text = configuration.rootDirectory
    }

    override fun applyEditorTo(configuration: RunConfiguration) {
        configuration.compiler = compilerList[compilerComboBox.selectedIndex]
        configuration.rootDirectory = rootDirectoryTextField.text
    }

    override fun createEditor(): JComponent? {
        rootDirectoryBrowseButton.addLabelFor(rootDirectoryTextField)

}
