public class Assistant {

	/**
	 * The main method.
	 * 
	 * @param args
	 *            the arguments
	 */
	public static void main(String[] args) {
		try {
			if (args.length == 0) {
				throw new CommandException("No command given.");
			}
			Map<String, Command> commands = new HashMap<String, Command>();
			commands.put("help", new nl.isaac.assistant.commands.Help());
			commands.put("exit", new nl.isaac.assistant.commands.Exit());
			commands.put("new", new nl.isaac.assistant.commands.New());
			commands.put("test", new nl.isaac.assistant.commands.Test());

			CommandListener listener = new CommandListener(commands);
			String line;
			while ((line = listener.readLine())!= null) {
				listener.parseCommand(line);
			}
		} catch (CommandException ex) {
			System.err.println(ex.getMessage());
		}
	}
}
