import java.util.Random;

public class RandomUtils {

    private static final Random random = new Random();

    private RandomUtils() {
    }

    public static boolean randomBoolean() {
        return random.nextBoolean();
    }

    public static double randomDouble() {
        return random.nextDouble();
    }

    public static double randomDouble(double min, double max) {
        return min + random.nextDouble() * (max - min);
    }

    public static int randomInteger(int min, int max) {
        return (int) (min + random.nextDouble() * (max - min));
    }

    public static long randomLong(long min, long max) {
        return min + random.nextLong() % (max - min);
    }

    public static <T extends Enum<T>> T randomEnum(Class<T> clazz) {
        return randomEnum(clazz, randomBoolean());
    }

    public static <T extends Enum<T>> T randomEnum(Class<T> clazz, boolean exclusive) {
        int x = exclusive? randomInteger(1, clazz.getEnumConstants().length) : randomInteger(0, clazz.getEnumConstants().length);
        return clazz.getEnumConstants()[x];
    }
}
