public class Problem13 extends Problem {

    @Override
    protected String getInput() {
        return "10";
    }

    @Override
    protected String getOutput() {
        AtomicInteger count = new AtomicInteger();

        List<String> numbers = new ArrayList<>();

        for (int i = 1; i <= 10; i++) {
            for (int j = 1; j <= 10; j++) {
                for (int k = 1; k <= 10; k++) {
                    if (i == j || j == k || i == k) {
                        continue;
                    }
                    if (i * i + j * j == k * k) {
                        numbers.add(String.format("%d^2 + %d^2 = %d^2", i, j, k));
                        count.incrementAndGet();
                    }
                }
            }
        }

        return count.get() + "\n" + String.join("\n", numbers);
    }
}
