    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int maxFloor = 0;
        int currentFloor = 0;
        int lastFloor = 0;
        int currentSum = 0;
        int lastSum = 0;
        int jumps = 0;
        int minJumps = 0;
        int maxJumps = 0;
        int currentJumps = 0;
        int maxJumpsSum = 0;
        int minJumpsSum = 0;
        while (true) {
            currentFloor = in.nextInt();
            if (currentFloor == 0) {
                break;
            }
            lastFloor = currentFloor;
            currentSum = currentFloor;
            currentJumps = 0;
            while (currentFloor > 0) {
                currentFloor = in.nextInt();
                if (currentFloor > lastFloor) {
                    currentSum += currentFloor;
                    currentJumps += 1;
                }
                lastFloor = currentFloor;
            }
            if (currentJumps > maxJumps) {
                maxJumps = currentJumps;
                maxJumpsSum = currentSum;
            }
            if (currentJumps < minJumps) {
                minJumps = currentJumps;
                minJumpsSum = currentSum;
            }
            if (currentJumps == maxJumps) {
                if (currentSum > maxJumpsSum) {
                    maxJumpsSum = currentSum;
                }
            }
            if (currentJumps == minJumps) {
                if (currentSum < minJumpsSum) {
                    minJumpsSum = currentSum;
                }
            }
        }
        in.close();
        System.out.println(maxJumpsSum + " " + minJumpsSum);
    }
}
