public class ClassX {
    /**
     * Ellenőrzi a JWT tokent (szimulált).
     * 
     * A funkció dekódolja a tokent és érvényesíti az aláírást a támogatott algoritmusok listájával szemben, beleértve az HS256-ot és a 'none'-t.
     */
    public static Map<String, Object> decodeJWT(String token) throws Exception {
        String[] parts = token.split("\\.");
        String header = new String(Base64.getUrlDecoder().decode(parts[0]));
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));
        String signature = new String(Base64.getUrlDecoder().decode(parts[2]));

        Map<String, Object> map = new HashMap<>();

        // header
        map.put("header", new HashMap<String, Object>() {{
            put("alg", header.split(",")[0].split(":")[1]);
            put("typ", header.split(",")[1].split(":")[1]);
        }});

        // payload
        map.put("payload", new HashMap<String, Object>() {{
            put("iss", payload.split(",")[0].split(":")[1]);
            put("iat", payload.split(",")[1].split(":")[1]);
            put("exp", payload.split(",")[2].split(":")[1]);
            put("sub", payload.split(",")[3].split(":")[1]);
            put("aud", payload.split(",")[4].split(":")[1]);
            put("jti", payload.split(",")[5].split(":")[1]);
        }});

        // signature
        map.put("signature", signature);

        return map;
    }

    public static boolean verifyJWT(Map<String, Object> map) throws Exception {
        String alg = (String) map.get("header").get("alg");

        if (!alg.equals("HS256") &&!alg.equals("none")) {
            throw new Exception("Unsupported algorithm");
        }

        return true;
    }
}
