        if (parts.length!= 3) {
            throw new IllegalArgumentException("invalid JWT token");
        }
        String header = Base64.getUrlDecoder().decode(parts[0]).toString();
        String claims = Base64.getUrlDecoder().decode(parts[1]).toString();
        String signature = parts[2];

        Map<String, Object> headerMap = new HashMap<>();
        Map<String, Object> claimsMap = new HashMap<>();
        try {
            headerMap = JSON.parseObject(header, Map.class);
            claimsMap = JSON.parseObject(claims, Map.class);
        } catch (JSONException e) {
            throw new IllegalArgumentException("invalid JWT token");
        }

        // 验证签名
        String algorithm = (String) headerMap.get("alg");
        if (!algorithm.equals("HS256") &&!algorithm.equals("none")) {
            throw new IllegalArgumentException("unsupported signature algorithm");
        }
        String key = "my-secret-key";
        if (algorithm.equals("none")) {
            key = "";
        }
        String expectedSignature = JWSHeader.computeSignature(claims, key, algorithm);
        if (!expectedSignature.equals(signature)) {
            throw new IllegalArgumentException("invalid JWT token");
        }

        // 验证有效期
        long now = System.currentTimeMillis() / 1000;
        long exp = (long) claimsMap.get("exp");
        if (exp < now) {
            throw new IllegalArgumentException("JWT token expired");
        }

        // 验证JWT令牌
        String type = (String) claimsMap.get("typ");
        if (!type.equals("JWT")) {
