public class DataUtil {
	public static String getString(Data data, DataType type) {
		return getString(data, type, true);
	}

	public static String getString(Data data, DataType type, boolean ignoreWhitespace) {
		if(data == null) {
			return null;
		}
		String result = data.getValue();
		if(result == null) {
			return null;
		}
		if(ignoreWhitespace) {
			result = result.replace("\n", " ").replace("\r", " ").replace("\t", " ").replace("\b", " ").replace("\f", " ").replace("\r\n", " ").replace("\u0000", " ");
		}
		return result;
	}

	public static Data getSingleData(Data data) {
		if(data == null || data.getValue() == null) {
			return null;
		}
		if(data.getValue().contains("|")) {
			return getSingleData(data.getValue().split("\\|")[0]);
		}
		return data;
	}

	public static List<Data> getMultipleData(Data data) {
		List<Data> result = new ArrayList<Data>();
		if(data == null || data.getValue() == null) {
			return result;
		}
		if(data.getValue().contains("|")) {
			for(String s : data.getValue().split("\\|")) {
				result.add(getSingleData(s));
			}
		} else {
			result.add(data);
		}
		return result;
	}

