/**
 * <pre>
 * 10)
 * Given two strings, return a new string made of the first char of each. If
 * either string is length 0, use '@' for its missing char.
 *
 * string_match("xxff", "yy") → "xy"
 * string_match("xxff", "yyy") → "xy"
 * string_match("xxff", "") → "@@"
 * </pre>
 */
public class Exercise10 {

    public static void main(String[] args) {
        System.out.println(stringMatch("xxff", "yy"));
        System.out.println(stringMatch("xxff", "yyy"));
        System.out.println(stringMatch("xxff", ""));
    }

    public static String stringMatch(String a, String b) {
        return a.length() < 1 || b.length() < 1
               ? "@@".substring(0, 2)
                : a.substring(0, 1) + b.substring(0, 1);
    }
}
