public class Assistant {

    private final CommandFactory commandFactory;

    public Assistant(CommandFactory commandFactory) {
        this.commandFactory = commandFactory;
    }

    /**
     * Executa um comando de assistência.
     *
     * @param input O texto do comando de assistência.
     * @return O resultado do comando de assistência.
     */
    public CommandResult run(String input) {
        List<Command> commands = CommandFactory.createCommands(input);
        List<CommandResult> results = new ArrayList<>();

        for (Command command : commands) {
            CommandResult result = commandFactory.getCommand(command.getType()).execute(command);
            results.add(result);
        }

        return CommandResult.combineResults(results);
    }

}
