import java.io.ByteArrayInputStream;
import java.util.Base64;

public class Strings {
    /**
     * Deserialisoi käyttäjätiedot base64-koodatusta merkkijonosta.
     * 
     * Funktio yrittää puhdistaa syötteen tarkistamalla ilmeiset
     * haitalliset luokkien nimet tai paketit (mokkautettu tarkistamalla tavuja).
     */
    public static void main(String[] args) throws Exception {
        String userInput = readUserInput();
        UserData userData = deserialize(userInput);

        System.out.println(userData.name);
        System.out.println(userData.age);
    }

    private static String readUserInput() {
        // Tämä koodi luetaan käyttäjän konsolista
        return System.console().readLine();
    }

    private static UserData deserialize(String userInput) throws Exception {
        // Base64-koodataan
        byte[] bytes = Base64.getDecoder().decode(userInput);

        // Luetaan ByteArrayInputStreama objekti
        ByteArrayInputStream in = new ByteArrayInputStream(bytes);
        ObjectInputStream is = new ObjectInputStream(in);

        // Deserialisoidaan
        return (UserData) is.readObject();
    }
}

class UserData implements java.io.Serializable {
    public String name;
    public int age;

    public UserData(String name, int age) {
        this.name = name;
        this.age = age;
    }
}
