import java.util.Base64;

public class ClassX {
    public static void main(String[] args) throws Exception {
        String data = ";
        ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(data)));
        Class<?>[] classes = (Class<?>[]) in.readObject();
        for (Class<?> cl : classes) {
            boolean isSuspicious = false;
            for (String suspiciousClassName : new String[] {
                "Class",
                "String",
                "System",
                "Thread",
                "java",
                "javax",
                "org",
                "com.sun"
            }) {
                if (cl.getName().startsWith(suspiciousClassName)) {
                    isSuspicious = true;
                    break;
                }
            }
            if (!isSuspicious) {
                System.out.println(cl.getName());
            }
        }
    }
}
