package nl.tudelft.informatica.ide.assistant.commands;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import nl.tudelft.informatica.ide.assistant.Assistant;
import nl.tudelft.informatica.ide.assistant.AssistantException;
import nl.tudelft.informatica.ide.assistant.commands.input.Input;
import nl.tudelft.informatica.ide.assistant.commands.output.Output;

public abstract class CommandBase {
	private String name;
	private String description;
	private List<String> aliases;

	public CommandBase(String name, String description) {
		this.name = name.toLowerCase();
		this.description = description;

		aliases = new ArrayList<>();
	}

	public String getName() {
		return name;
	}

	public String getDescription() {
		return description;
	}

	public List<String> getAliases() {
		return aliases;
	}

	public void addAlias(String alias) {
		alias = alias.toLowerCase();

		if (aliases.contains(alias)) {
			return;
		}

		aliases.add(alias);
	}

	public void execute(Assistant assistant, Input input, Output output) throws AssistantException {
		try {
			doExecute(assistant, input, output);
		} catch (IOException e) {
			throw new AssistantException("Error while executing command: " + e.getMessage(), e);
		}
	}

	protected abstract void doExecute(Assistant assistant, Input input, Output output) throws AssistantException, IOException;
}
