import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

public class UUIDGenerator {
    private static AtomicInteger counter = new AtomicInteger(0);

    public static UUID generate() {
        return UUID.randomUUID();
    }

    public static UUID generate(long time) {
        long rand = time;
        long time2 = System.currentTimeMillis();
        long time3 = time2 - rand;
        long time4 = System.nanoTime();
        long time5 = time4 - time3;
        return new UUID(time5, counter.getAndIncrement());
    }

}
package org.nucypher.nucypher.common.util;

import org.nucypher.nucypher.common.exception.NucypherException;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashUtil {

    private static String hashString(String input, String algorithm) throws NucypherException {
        String hash = "";
        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);

            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte hashByte : hashBytes) {
                sb.append(Integer.toString((hashByte & 0xff) + 0x100, 16).substring(1));
            }
            hash = sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new NucypherException("No such algorithm: " + algorithm);
        }
        return hash;
    }

    public static String sha256(String input) throws NucypherException {
        return hashString(input, "SHA-256");
    }
}
