package fr.unice.polytech.si3.a2020.tp2.controller;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.servlet.ModelAndView;

import fr.unice.polytech.si3.a2020.tp2.service.LoginService;

@Controller
public class LoginController {
	private LoginService loginService;

	public LoginController(LoginService loginService) {
		this.loginService = loginService;
	}

	@RequestMapping(method = RequestMethod.GET, value = "/login")
	public ModelAndView login() {
		ModelAndView mv = new ModelAndView("login");
		mv.addObject("login", new Login());
		return mv;
	}

	@RequestMapping(method = RequestMethod.POST, value = "/login")
	public ModelAndView login(@ModelAttribute Login login) {
		ModelAndView mv;
		if (loginService.isValid(login)) {
			mv = new ModelAndView("welcome");
			mv.addObject("name", login.getUsername());
		} else {
			mv = new ModelAndView("login");
			mv.addObject("login", login);
			mv.addObject("loginError", "Invalid username or password");
		}
		return mv;
	}
}
