package it.unibs.inf.java.robuste.security.security;

import java.util.ArrayList;
import java.util.List;

import it.unibs.inf.java.robuste.security.model.User;

public class Security {

    private List<User> users;
    private List<String> blackList;

    public Security() {
        users = new ArrayList<User>();
        blackList = new ArrayList<String>();
    }

    public boolean isBlackList(String url) {
        return blackList.contains(url);
    }

    public boolean isLogged(String name) {
        User user = findUser(name);
        return user!= null && user.isLogged();
    }

    public User findUser(String name) {
        User user = null;
        for (User u : users) {
            if (u.getName().equals(name)) {
                user = u;
                break;
            }
        }
        return user;
    }

    public User addUser(User user) {
        users.add(user);
        return user;
    }

    public User addBlackList(String domain) {
        User user = new User();
        users.add(user);
        blackList.add(domain);
        return user;
    }

    public User addBlackList(User user) {
        users.add(user);
        blackList.add(user.getDomain());
        return user;
    }
}
