import javax.servlet.http.HttpSession;

import core.utils.SessionUtils;
import web.controllers.AbstractController;

@WebServlet(name = "Home", urlPatterns = "/home")
public class HomeController extends AbstractController {
	private static final long serialVersionUID = 1L;

	@Override
	protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
		HttpSession session = req.getSession();
		session.setAttribute("title", "Home");
		session.setAttribute("content", "home.jsp");

		if(SessionUtils.isLoggedIn(req)){
			session.setAttribute("username", SessionUtils.getUsername(req));
		}

		req.getRequestDispatcher("/WEB-INF/views/index.jsp").forward(req, resp);
	}

	@Override
	protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
		doGet(req, resp);
	}
}
