@WebServlet("/codeassist")
public class Codeassist extends HttpServlet {
    private static final long serialVersionUID = 1L;

    @Override
    public void init() throws ServletException {
        super.init();
        Code.init(getServletContext().getInitParameter("dataDir"));
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String system = request.getParameter("system");
        String question = request.getParameter("question");
        String snippet = request.getParameter("snippet");
        String message = request.getParameter("message");

        if (!Code.isValid(system, question, snippet, message)) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
