 * A user of the application.
 */
public class User implements Comparable<User> {
	/**
	 * The username of the user.
	 */
	private String username;

	/**
	 * The list of scores of the user.
	 */
	private List<Score> scores;

	/**
	 * Creates a new user.
	 * @param username the username of the user.
	 */
	public User(String username) {
		this.username = username;
		scores = new ArrayList<Score>();
	}

	/**
	 * @return the username of the user.
	 */
	public String getUsername() {
		return username;
	}

	/**
	 * @return the list of scores of the user.
	 */
	public List<Score> getScores() {
		return scores;
	}

	/**
	 * Adds a score to the user.
	 * @param score the score to add.
	 */
	public void addScore(Score score) {
		scores.add(score);
	}

	@Override
	public int compareTo(User other) {
		if (this.scores.size() == 0 || other.scores.size() == 0) return 0;
		int result = other.scores.get(0).compareTo(this.scores.get(0));
		if (result == 0) {
			for (int i = 1; i < this.scores.size() && i < other.scores.size(); i++) {
				result = other.scores.get(i).compareTo(this.scores.get(i));
				if (result!= 0) break;
			}
		}
		return result;
	}
}
