    public void redirectToUrl(String url, HttpServletResponse response) throws InvalidDomainException {
        String[] parts = url.split("://");
        if (parts.length!= 2) {
            throw new InvalidDomainException("Url is invalid");
        }
        String host = parts[1];
        String[] parts2 = host.split("\\.");
        if (parts2.length < 2) {
            throw new InvalidDomainException("Url is invalid");
        }
        String domain = parts2[parts2.length - 2] + "." + parts2[parts2.length - 1];
