import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.github.sebastian_daschner.exampro.generator.generator.Generator;

/**
 * The default implementation of the Generator interface.
 * 
 * @author 
 */
public abstract class DefaultGenerator implements Generator {

    private static final Pattern VAR_PATTERN = Pattern.compile("\\$\\{([^}]+)}");
    private static final Pattern EXTRA_PATTERN = Pattern.compile("\\$\\{([^}]+)\\s+([0-9]+)}");

    private final Map<String, String> variables = new HashMap<String, String>();
    private final Map<String, String> extraVariables = new HashMap<String, String>();

    @Override
    public String generate(String template) {
        String result = template;
        Matcher matcher = VAR_PATTERN.matcher(result);
        while (matcher.find()) {
            String varName = matcher.group(1);
            String varValue = getVariable(varName);
            if (varValue == null) {
                throw new IllegalStateException("Variable '" + varName + "' is not defined");
            }
            result = result.replace("$" + matcher.group(), varValue);
        }

        matcher = EXTRA_PATTERN.matcher(result);
        while (matcher.find()) {
            String varName = matcher.group(1);
            String varValue = getExtraVariable(varName);
            if (varValue == null) {
                throw new IllegalStateException("Variable '" + varName + "' is not defined");
            }
            int count = Integer.parseInt(matcher.group(2));
            String extra = "";
            for (int i = 0; i < count; i++) {
                extra += varValue + "\n";
            }
            result = result.replace("$" + matcher.group(), extra);
        }
        return result;
    }

}

