public class Main {

    private static List<String> myList;

    public static void main(String[] args) {
        myList = new ArrayList<>();
        myList.add("A");
        myList.add("B");
        myList.add("C");
        myList.add("D");
        myList.add("E");
        myList.add("F");
        myList.add("G");
        myList.add("H");
        myList.add("I");
        myList.add("J");
        myList.add("K");
        myList.add("L");

        for (String s : myList) {
            System.out.print(s + " ");
        }

        System.out.println("");
        System.out.println("Reverse: ");
        myList = reverse(myList);
        for (String s : myList) {
            System.out.print(s + " ");
        }
    }

    private static List<String> reverse(List<String> list) {
        List<String> reversedList = new ArrayList<>(list);
        for (int i = 0; i < reversedList.size() / 2; i++) {
            String temp = reversedList.get(i);
            reversedList.set(i, reversedList.get(reversedList.size() - 1 - i));
            reversedList.set(reversedList.size() - 1 - i, temp);
        }
        return reversedList;
    }
}
