package fi.helsinki.cs.tmc.grader.utils;

import java.io.File;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;

public class IOUtils {
	public static void saveClass(Object o, String fileName) throws IOException {
		File f = new File(fileName);
		if (!f.getParentFile().exists()) {
			f.getParentFile().mkdirs();
		}
		f.createNewFile();

		ObjectOutputStream oos = new ObjectOutputStream(f.getOutputStream());
		oos.writeObject(o);
		oos.close();
	}

	public static Object loadClass(String fileName) throws ClassNotFoundException, IOException,
			IllegalAccessException, InstantiationException {
		File f = new File(fileName);
		if (f.exists()) {
			ObjectInputStream ois = new ObjectInputStream(f.getInputStream());
			Object o = ois.readObject();
			ois.close();
			return o;
		} else {
			throw new IOException("Class '" + fileName + "' does not exist.");
		}
	}
}
