package br.com.codenation.challenge.service;

import br.com.codenation.challenge.domain.Challenge;
import br.com.codenation.challenge.domain.User;
import br.com.codenation.challenge.repository.ChallengeRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

@Service
@Transactional
public class ChallengeService {

    private final ChallengeRepository repository;

    public ChallengeService(ChallengeRepository repository) {
        this.repository = repository;
    }

    public List<Challenge> findChallengesByUserId(long userId) {
        Optional<User> user = this.repository.findUserById(userId);
        if (user.isPresent()) {
            return this.repository.findChallengesByUserId(user.get().getId());
        }
        return null;
    }

    public List<Challenge> findChallengesByUserIdAndStatus(long userId) {
        Optional<User> user = this.repository.findUserById(userId);
        if (user.isPresent()) {
            return this.repository.findChallengesByUserIdAndStatus(user.get().getId());
        }
        return null;
    }

    public List<Challenge> findChallengesByUserIdAndStatusAndLevel(long userId, String status, String level) {
        Optional<User> user = this.repository.findUserById(userId);
        if (user.isPresent()) {
            return this.repository.findChallengesByUserIdAndStatusAndLevel(user.get().getId(), status, level);
        }
        return null;
    }

    public Challenge findChallengeById(long challengeId) {
        Optional<Challenge> challenge = this.repository.findChallengeById(challengeId);
        if (challenge.isPresent()) {
            return challenge.get();
        }
        return null;
    }

    public Challenge saveChallenge(Challenge challenge) {
        return this.repository.save(challenge);
    }

    public void deleteChallenge(long challengeId) {
        this.repository.delete(this.findChallengeById(challengeId));
    }
}
