package com.codechef.challenge.challenge2018.easy;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.IntStream;

public class EasyChallenge2018 {

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine());
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < T; t++) {
            String[] line = br.readLine().split(" ");
            int N = Integer.parseInt(line[0]);
            int K = Integer.parseInt(line[1]);
            int[] A = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
            Map<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < N; i++) {
                map.put(A[i], map.getOrDefault(A[i], 0) + 1);
            }
            int[] sorted = map.keySet().stream().mapToInt(x -> x).toArray();
            Arrays.sort(sorted);
            int[] count = IntStream.range(0, N).map(i -> (int) (i / K) + 1).toArray();
            int[] result = new int[N];
            int j = 0;
            for (int i = 0; i < N; i++) {
                result[i] = sorted[j++] * count[i];
            }
            sb.append("Case #").append(t + 1).append(": ").append(Arrays.toString(result)).append("\n");
        }
        System.out.println(sb.toString());
    }

}
