import org.antlr.v4.runtime.CharStream;
import org.antlr.v4.runtime.CharStreams;
import org.antlr.v4.runtime.CommonTokenStream;
import org.antlr.v4.runtime.tree.ParseTree;
import org.antlr.v4.runtime.tree.ParseTreeWalker;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Challenge 3 : Classifier
 *
 * @author 
 */
public class Challenge3 extends Challenge {
    public Challenge3(File file, String name, String description) {
        super(file, name, description);
    }

    @Override
    public void solve(String answer) {
        try {
            // parse
            CharStream charStream = CharStreams.fromStream(new FileInputStream(file));
            ClassifierLexer lexer = new ClassifierLexer(charStream);
            CommonTokenStream tokens = new CommonTokenStream(lexer);
            ClassifierParser parser = new ClassifierParser(tokens);
            ParseTree tree = parser.program();

            // walk
            ClassifierListener listener = new ClassifierListener(answer);
            ParseTreeWalker walker = new ParseTreeWalker();
            walker.walk(listener, tree);

            // write
            PrintWriter out = new PrintWriter(new FileOutputStream(file));
            out.print(listener.getClassifier());
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

