import java.net.URL;

public class Solution {

    public static void main(String[] args) {
        try {
            InputStream in = new URL("https://corundum.com/").openStream();
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            int x;
            while ((x = in.read())!= -1) {
                out.write(x);
